import{_ as o,o as t,c as i,a3 as n}from"./chunks/framework.BveOjhN0.js";const g=JSON.parse('{"title":"Opportunities — Production Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Opportunities — Production Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/opportunities"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Opportunities — Production Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/opportunities"}]]},"headers":[],"relativePath":"deployment/opportunities.md","filePath":"deployment/opportunities.md","lastUpdated":1785449762000}'),s={name:"deployment/opportunities.md"};function a(r,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="opportunities-—-production-guide" tabindex="-1">Opportunities — Production Guide <a class="header-anchor" href="#opportunities-—-production-guide" aria-label="Permalink to &quot;Opportunities — Production Guide&quot;">​</a></h1><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>opportunities</code></li><li>Category: <strong>Sales</strong> (<code>sales</code>)</li><li><strong>Free Marketplace opt-in</strong> (not auto-installed)</li><li>Catalog flags: <code>is_default_included = false</code>, <code>is_billable = false</code>, price <code>0</code>, <code>sort_order = 40</code></li><li>New workspaces receive only <strong>Leads</strong> + <strong>Tasks</strong> by default; enable Opportunities from Marketplace</li><li><strong>Sales Pipeline</strong> is not a separate catalog row — stages and board ship inside this module</li><li>Existing workspaces that already have Opportunities keep their subscription (policy change does not uninstall)</li></ul><h2 id="bootstrap" tabindex="-1">Bootstrap <a class="header-anchor" href="#bootstrap" aria-label="Permalink to &quot;Bootstrap&quot;">​</a></h2><p>On <strong>new workspace</strong> create:</p><ol><li><code>installDefaultModules()</code> installs published <code>is_default_included</code> modules (<strong>Leads</strong>, <strong>Tasks</strong> only)</li><li>Operators enable Opportunities from Marketplace (free / non-billable install activates immediately)</li><li>Tenant permissions include <code>opportunities.*</code> via <code>config/tenant-permissions.php</code> / default role maps</li><li>First API use seeds default <code>opportunity_stages</code> via <code>OpportunityStageSeeder</code> (idempotent)</li></ol><h2 id="permissions-rollout" tabindex="-1">Permissions rollout <a class="header-anchor" href="#permissions-rollout" aria-label="Permalink to &quot;Permissions rollout&quot;">​</a></h2><p>New Opportunities permissions for <strong>existing</strong> workspaces ship as an additive <strong>data migration</strong> using <code>TenantPermissionSynchronizer::grantMissingDefaultRolePermissions([...])</code>. Do <strong>not</strong> re-seed roles.</p><h2 id="monitoring" tabindex="-1">Monitoring <a class="header-anchor" href="#monitoring" aria-label="Permalink to &quot;Monitoring&quot;">​</a></h2><ul><li>Platform audit events: <code>opportunity_created</code>, <code>opportunity_updated</code>, <code>opportunity_deleted</code>, <code>opportunity_assigned</code>, <code>opportunity_stage_changed</code>, <code>opportunity_note_added</code></li><li>Notifications: assignment via <code>OpportunityAssignedNotification</code></li></ul><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Migrate tables (<code>opportunity_stages</code>, <code>opportunities</code>, <code>opportunity_notes</code>, <code>opportunity_activities</code>)</li><li>Register the <code>opportunities</code> catalog module via migration (<code>DefaultModuleRegistrar</code>) as free Sales opt-in — <strong>not</strong> <code>db:seed</code></li><li>Run opportunities permissions migration so default roles receive missing <code>opportunities.*</code> grants</li><li>Confirm <code>module:opportunities</code> + <code>opportunities.*</code> permissions on target roles</li><li>Deploy Frontend SPA with Opportunities nav/pages (mirror Leads board + table) when the SPA ships</li></ol>',12)])])}const m=o(s,[["render",a]]);export{g as __pageData,m as default};
